mark2=set()
for dr,dc in [(0,1),(1,0)]:
 for r in range(R):
  for c in range(C):
   if g[r][c]!=4: continue
   rr,cc=r+dr,c+dc; run=[]
   while 0<=rr<R and 0<=cc<C and g[rr][cc]==9:
    run.append((rr,cc)); rr+=dr; cc+=dc
   if run and 0<=rr<R and 0<=cc<C and g[rr][cc]==4:
    mark2.update(run)
out2=[[2 if (r,c) in mark2 else v for c,v in enumerate(row)] for r,row in enumerate(g)]
print('\n'.join(' '.join(map(str,x)) for x in out2)); print(sorted(mark2))

marks=set()
for r,row in enumerate(g):
 cs=[c for c,v in enumerate(row) if v==4]
 if len(cs)>=3:
  for a,b in zip(cs,cs[1:]):
   for c in range(a+1,b):
    if g[r][c]==9: marks.add((r,c))
for c in range(C):
 rs=[r for r in range(R) if g[r][c]==4]
 if len(rs)>=3:
  for a,b in zip(rs,rs[1:]):
   for r in range(a+1,b):
    if g[r][c]==9: marks.add((r,c))
